import { deepCopy } from '@/components/canvas/utils/utils'

const snapshot = {
  data() {
    return {
      snapshotData: [], // 编辑器快照数据
      snapshotStyleData: [], // 样式改变也记录快照
      snapshotIndex: -1, // 快照索引
      changeTimes: -1, // 修改次数
      lastSaveSnapshotIndex: 0, // 最后保存是snapshotIndex的索引
      styleChangeTimes: 0, // 组件样式修改次数
      doSnapshotIndex: -1 // snapshot undo redo 时的索引记录
    }
  },
  methods: {
    undo() {
      this.setCurComponent({ component: null, index: null })
      if (this.snapshotIndex > 0) {
        this.snapshotIndex--
        this.doSnapshotIndex = this.snapshotIndex
        this.setComponentData(deepCopy(this.snapshotData[this.snapshotIndex]))
        this.setCanvasStyle(deepCopy(this.snapshotData[this.snapshotIndex]))
      }
    },
    redo() {
      this.setCurComponent({ component: null, index: null })
      if (this.snapshotIndex < this.snapshotData.length - 1) {
        this.snapshotIndex++
        this.doSnapshotIndex = this.snapshotIndex
        this.setComponentData(deepCopy(this.snapshotData[this.snapshotIndex]))
        this.setCanvasStyle(deepCopy(this.snapshotStyleData[this.snapshotIndex]))
      }
    },

    recordSnapshot() {
      this.changeTimes++
      // console.log('recordSnapshot')
      // 添加新的快照
      this.snapshotData[++this.snapshotIndex] = deepCopy(this.componentData)
      this.snapshotStyleData[this.snapshotIndex] = deepCopy(this.canvasStyleData)
      // 在 undo 过程中，添加新的快照时，要将它后面的快照清理掉
      if (this.snapshotIndex < this.snapshotData.length - 1) {
        this.snapshotData = this.snapshotData.slice(0, this.snapshotIndex + 1)
        this.snapshotStyleData = this.snapshotStyleData.slice(0, this.snapshotIndex + 1)
      }
    },
    refreshSnapshot() {
      // console.log('refreshSnapshot')
      // 刷新快照
      this.snapshotData = []
      this.snapshotStyleData = []
      this.snapshotIndex = -1
      this.changeTimes = -1
      this.lastSaveSnapshotIndex = 0
    },
    refreshSaveStatus() {
      this.changeTimes = 0
      this.lastSaveSnapshotIndex = deepCopy(this.snapshotIndex)
    },
    recordStyleChange() {
      if (this.curComponent) {
        this.styleChangeTimes++
      }
    }
  }
}

export default snapshot
