const panel = {
  data() {
    return {
      panelName: '',
      panelInfo: {
        id: null,
        name: '',
        preStyle: null
      },
      canvasStyleDataTemp: null, // 页面全局临时存储数据
      componentDataTemp: null, // 画布组件临时存储数据
      mainActiveName: 'PanelMain'
    }
  },
  methods: {
    setPanelName(panelName) {
      this.panelName = panelName
    },
    setMainActiveName(mainActiveName) {
      this.mainActiveName = mainActiveName
    },
    setPanelInfo(panelInfo) {
      this.panelInfo = panelInfo
    },
    setCanvasStyleDataTemp(canvasStyleDataTemp) {
      this.canvasStyleDataTemp = canvasStyleDataTemp
    },
    setComponentDataTemp(componentDataTemp) {
      this.componentDataTemp = componentDataTemp
    }
  }
}

export default panel
