import { login, logout, getInfo, getUIinfo, languageApi } from '@/api/user'
import { getToken, setToken, removeToken, setSysUI } from '@/utils/auth'
// import { resetRouter } from '@/router'
import { format } from '@/utils/formatUi'
// import { getLanguage } from '@/lang/index'
import Cookies from 'js-cookie'
// import router from '@/router'
// import i18n from '@/lang'

const user = {
  data() {
    return {
      token: getToken(),
      name: '',
      user: {},
      roles: [],
      avatar: '',
      // 第一次加载菜单时用到
      loadMenus: false,
      // 当前用户拥有哪些资源权限
      permissions: [],
      // language: getLanguage(),
      uiInfo: null,
      linkToken: null
    }
  },
  methods: {
    // user login
    login(userInfo) {
      const { username, password, loginType } = userInfo
      return new Promise((resolve, reject) => {
        login({ username: username.trim(), password: password, loginType: loginType }).then(response => {
          const { data } = response
          this.token = data.token
          this.loginMsg = null
          setToken(data.token)
          resolve()
        }).catch(error => {
          reject(error)
        })
      })
    },
    refreshToken({ commit }, token) {
      this.token = token
      setToken(token)
    },

    // get user info
    getInfo() {
      return new Promise((resolve, reject) => {
        getInfo(this.token).then(response => {
          const { data } = response

          if (!data) {
            reject('Verification failed, please Login again.')
          }
          localStorage.setItem('userId', data.userId)
          const currentUser = data
          this.user = currentUser

          const { roles, nickName, permissions, language } = data
          this.roles = roles

          this.name = nickName
          // commit('SET_AVATAR', avatar)

          this.permissions = permissions

          this.language = language
          Cookies.set('language', language)

          // axios.defaults.headers.common['Accept-Language'] = language || 'zh_CN'
          // document.querySelector('html').setAttribute('lang', language || 'zh_CN')
          resolve(data)
        }).catch(error => {
          reject(error)
        })
      })
    },

    getUI() {
      return new Promise((resolve, reject) => {
        getUIinfo().then(response => {
          const { data } = response
          const uiInfo = format(data)
          this.uiInfo = uiInfo
          setSysUI(uiInfo)
          resolve(uiInfo)
        }).catch(error => {
          reject(error)
        })
      })
    },

    // user logout
    logout() {
      return new Promise((resolve, reject) => {
        logout(this.token).then(() => {
          removeToken() // must remove  token  first
          // resetRouter()
          // this.$data 获取当前状态下的data
          // this.$options.data() 获取该组件初始状态下的data
          Object.assign(this.$data, this.$options.data())
          resolve()
        }).catch(error => {
          reject(error)
        })
      })
    },
    updateLoadMenus() {
      return new Promise((resolve, reject) => {
        this.loadMenus = false
      })
    },

    // remove token
    resetToken() {
      return new Promise(resolve => {
        removeToken() // must remove  token  first
        Object.assign(this.$data, this.$options.data())
        resolve()
      })
    },
    setLoginMsg(msg) {
      this.loginMsg = msg
    },
    setLanguage(language) {
      languageApi(language).then(() => {
        this.language = language
        Cookies.set('language', language)
        // router.go(0)
      })
    },
    setLinkToken({ commit }, linkToken) {
      this.linkToken = linkToken
    }
  }
}

export default user
