<template>
  <el-row
    v-loading="dataLoading"
    style="height: 100%;width: 100%;"
    :element-loading-text="$t('panel.data_loading')"
    element-loading-spinner="el-icon-loading"
    element-loading-background="rgba(0, 0, 0, 1)"
  >
    <el-col v-if="panelInfo.hasOwnProperty('name') && panelInfo.name.length>0" class="panel-design">
      <el-row class="panel-design-head">
        <!--仪表板头部区域-->
        <div style="height: 100%;">
          <el-col :span="12" style="text-overflow:ellipsis;overflow: hidden;white-space: nowrap;font-size: 14px">
            <span style="margin-left: 10px">{{ panelInfo.name || '测试仪表板' }}</span>
            &nbsp;
            <span v-if="panelInfo.isDefault" style="color: green;font-size: 12px">({{ $t('panel.default_panel_name') }}:{{ panelInfo.defaultPanelName }})</span>
            <span v-if="panelInfo.sourcePanelName" style="color: green;font-size: 12px">({{ $t('panel.source_panel_name') }}:{{ panelInfo.sourcePanelName }})</span>
          </el-col>
          <el-col :span="12">
            <span style="float: right;margin-right: 10px">
              <el-tooltip content="截图">
                <el-button class="el-icon-picture-outline" :loading="isCaptured" size="mini" circle @click="clickCaptureImg" />
              </el-tooltip>
            </span>

            <span style="float: right;margin-right: 10px">
              <el-tooltip :content="$t('panel.export_to_pdf')">
                <el-button class="el-icon-notebook-2" size="mini" circle @click="downloadAsPDF" />
              </el-tooltip>
            </span>
            <span style="float: right;margin-right: 10px">
              <el-tooltip :content="$t('panel.fullscreen_preview')">
                <el-button class="el-icon-view" size="mini" circle @click="clickFullscreen" />
              </el-tooltip>
            </span>

            <span style="float: right;margin-right: 10px">
              <el-tooltip :content="$t('panel.new_tab_preview')">
                <el-button class="el-icon-data-analysis" size="mini" circle @click="newTab" />
              </el-tooltip>
            </span>

            <span v-if="!hasStar && panelInfo" style="float: right;margin-right: 10px">
              <el-tooltip :content="$t('panel.store')">
                <el-button class="el-icon-star-off" size="mini" circle @click="star" />
              </el-tooltip>
            </span>

            <span v-if="hasStar && panelInfo" style="float: right;margin-right: 10px">
              <el-tooltip :content="$t('commons.cancel')">
                <el-button class="el-icon-star-on" size="mini" circle @click="unstar" />
              </el-tooltip>
            </span>

          </el-col>
        </div>
      </el-row>
      <!-- 仪表板预览区域-->
      <el-row class="panel-design-preview">
        <div id="imageWrapper" ref="imageWrapper" :style="imageWrapperStyle">
          <fullscreen style="height: 100%;background: #f7f8fa;overflow-y: auto" :fullscreen.sync="fullscreen">
            <Preview
              :canvasInfoTempId='canvasInfoTempId'
              v-if="showMainFlag"
              :in-screen="!fullscreen"
              :show-type="'width'"
              :screen-shot="dataLoading"
              :is-click-component="isClickComponent"
              :component-data="componentData"
              :canvas-style-data="canvasStyleData"
              :now-panel-track-info="nowPanelTrackInfo"
              :now-panel-jump-info="nowPanelJumpInfo"/>
          </fullscreen>
        </div>
      </el-row>
    </el-col>
    <el-col v-if="!panelInfo.name || panelInfo.name.length===0" style="height: 100%;">
      <el-row style="height: 100%; background-color: var(--ContentBG);" class="custom-position">
        {{ $t('panel.select_panel_from_left') }}
      </el-row>
    </el-col>

    <el-dialog
      v-if="templateSaveShow"
      :title="templateSaveTitle"
      :visible.sync="templateSaveShow"
      width="500px"
    >
      <save-to-template :template-info="templateInfo" @closeSaveDialog="closeSaveDialog" />
    </el-dialog>
    <el-dialog
      v-if="pdfExportShow"
      :title="'['+panelInfo.name+']'+'PDF导出'"
      :visible.sync="pdfExportShow"
      width="80%"
      :top="'8vh'"
      :destroy-on-close="true"
      class="dialog-css2"
    >
      <span style="position: absolute;right: 70px;top:15px">
        <svg-icon icon-class="PDF" class="ds-icon-pdf" />
        <el-select v-model="pdfTemplateSelectedIndex" :placeholder="'切换PDF模板'" @change="changePdfTemplate()">
          <el-option
            v-for="(item, index) in pdfTemplateAll"
            :key="index"
            :label="item.name"
            :value="index"
          />
        </el-select>
      </span>
      <PDFPreExport
        :snapshot="snapshotInfo"
        :panel-name="panelInfo.name"
        :template-content="pdfTemplateContent"
        @closePreExport="closePreExport"
        :user="user"/>
    </el-dialog>
  </el-row>
</template>
<script>
import PDFPreExport from '@/views/panel/export/PDFPreExport'
import Preview from '@/components/canvas/components/Editor/Preview'
// import { mapState } from 'vuex'
import html2canvas from 'html2canvasde'
import FileSaver from 'file-saver'
import { starStatus, saveEnshrine, deleteEnshrine } from '@/api/panel/enshrine'
import bus from '@/utils/bus'
import { queryAll } from '@/api/panel/pdfTemplate'
import captureImg from '@/utils/captureImg'
import { uuid } from 'vue-uuid'

export default {
  name: 'PanelViewShow',
  components: { Preview, PDFPreExport },
  props: {
    activeTab: {
      type: String,
      required: false
    },
    // store 源数据
    isClickComponent: {
      type: Boolean,
      default: false
    },
    componentData: {
      type: Array,
      default: () => []
    },
    canvasStyleData: {
      type: Object,
      default: null
    },
    panelInfos: {
      type: Object,
      default: () => ({
        id: null,
        name: '',
        preStyle: null
      })
    },
    user: {
      type: Object,
      default: () => {}
    },
    nowPanelTrackInfo: {
      type: Object,
      default: () => {}
    },
    nowPanelJumpInfo: {
      type: Object,
      default: () => {}
    }
  },
  data() {
    return {
      canvasInfoTempId: uuid.v1(),
      showMain: true,
      pdfTemplateSelectedIndex: 0,
      pdfTemplateContent: '',
      templateInfo: {},
      pdfTemplateAll: [],
      templateSaveTitle: '保存为模板',
      templateSaveShow: false,
      hasStar: false,
      fullscreen: false,
      pdfExportShow: false,
      snapshotInfo: '',
      showType: 0,
      dataLoading: false,
      exporting: false
    }
  },
  computed: {
    imageWrapperStyle() {
      if (this.exporting) {
        return {
          width: '4096px',
          height: '2160px'
        }
      } else {
        return {
          width: '100%',
          height: '100%'
        }
      }
    },
    showMainFlag() {
      return this.showMain
    },
    panelInfo() {
      // return this.$store.state.panel.panelInfo
      return this.panelInfos
    }
    // ...mapState(
    //   {
    //     componentData: state => state.report.componentData,
    //     canvasStyleData: state => state.report.canvasStyleData
    //   }
    // )
  },
  watch: {
    panelInfo(newVal, oldVla) {
      // 刷新 进行重新渲染
      this.showMain = false

      this.$nextTick(() => {
        this.showMain = true
        this.initHasStar()
      })
    },
    fullscreen(newVal, oldVla) {
      // 刷新 进行重新渲染
      this.showMain = false
      this.$nextTick(() => {
        this.showMain = true
        this.initHasStar()
      })
    }
  },
  mounted() {
    bus.$on('set-panel-show-type', type => {
      this.showType = type || 0
    })
    this.initPdfTemplate()
  },
  methods: {
    initPdfTemplate() {
      queryAll().then(res => {
        this.pdfTemplateAll = res.data
        this.changePdfTemplate()
      })
    },
    async clickCaptureImg() {
      this.isCaptured = true
      let imageWrapper = this.$refs.imageWrapper;
      await captureImg(imageWrapper);
      this.isCaptured = false
    },
    clickFullscreen() {
      this.fullscreen = true
    },
    newTab() {
      // const url = '#/preview/' + this.$store.state.panel.panelInfo.id
      const url = '#/preview/' + this.panelInfo.id
      window.open(url, '_blank')
    },
    saveToTemplate() {
      this.dataLoading = true
      setTimeout(() => {
        html2canvas(document.getElementById(this.canvasInfoTempId)).then(canvas => {
          this.templateSaveShow = true
          this.dataLoading = false
          const snapshot = canvas.toDataURL('image/jpeg', 0.1) // 0.2是图片质量
          if (snapshot !== '') {
            this.templateInfo = {
              // name: this.$store.state.panel.panelInfo.name,
              name: this.panelInfo.name,
              snapshot: snapshot,
              templateStyle: JSON.stringify(this.canvasStyleData),
              templateData: JSON.stringify(this.componentData),
              templateType: 'self',
              nodeType: 'template',
              level: 1,
              pid: null,
              dynamicData: ''
            }
          }
        })
      }, 50)
    },
    downloadToTemplate() {
      this.dataLoading = true
      setTimeout(() => {
        html2canvas(document.getElementById(this.canvasInfoTempId)).then(canvas => {
          this.dataLoading = false
          const snapshot = canvas.toDataURL('image/jpeg', 0.1) // 0.2是图片质量
          if (snapshot !== '') {
            this.templateInfo = {
              // name: this.$store.state.panel.panelInfo.name,
              name: this.panelInfo.name,
              templateType: 'self',
              snapshot: snapshot,
              panelStyle: JSON.stringify(this.canvasStyleData),
              panelData: JSON.stringify(this.componentData),
              dynamicData: ''
            }
            const blob = new Blob([JSON.stringify(this.templateInfo)], { type: '' })
            // FileSaver.saveAs(blob, this.$store.state.panel.panelInfo.name + '-TEMPLATE.DE')
            FileSaver.saveAs(blob, this.panelInfo.name + '-TEMPLATE.DE')
          }
        })
      }, 50)
    },

    downloadAsPDF() {
      // this.pdfExportShow = true
      //
      this.dataLoading = true

      setTimeout(() => {
        this.exporting = true
        setTimeout(() => {
          html2canvas(document.getElementById(this.canvasInfoTempId)).then(canvas => {
            const snapshot = canvas.toDataURL('image/jpeg', 1) // 是图片质量
            this.dataLoading = false
            this.exporting = false
            if (snapshot !== '') {
              this.snapshotInfo = snapshot
              this.pdfExportShow = true
            }
          })
        }, 1500)
      }, 500)
    },
    refreshTemplateInfo() {
      this.templateInfo = {}
      html2canvas(document.getElementById(this.canvasInfoTempId)).then(canvas => {
        const snapshot = canvas.toDataURL('image/jpeg', 0.1) // 0.2是图片质量
        if (snapshot !== '') {
          this.templateInfo = {
            snapshot: snapshot,
            panelStyle: JSON.stringify(this.canvasStyleData),
            panelData: JSON.stringify(this.componentData),
            dynamicData: ''
          }
        }
      })
    },
    closeSaveDialog() {
      this.templateSaveShow = false
    },
    star() {
      this.panelInfo && saveEnshrine(this.panelInfo.id).then(res => {
        this.hasStar = true
        this.refreshStarList(true)
      })
    },
    unstar() {
      this.panelInfo && deleteEnshrine(this.panelInfo.id).then(res => {
        this.hasStar = false
        this.refreshStarList(false)
      })
    },
    initHasStar() {
      starStatus(this.panelInfo.id).then(res => {
        this.hasStar = res.data
      })
    },
    refreshStarList(isStar) {
      if (this.activeTab !== 'PanelList') {
        bus.$emit('panle_start_list_refresh', isStar)
      }
    },
    changePdfTemplate() {
      this.pdfTemplateContent = this.pdfTemplateAll[this.pdfTemplateSelectedIndex] ? this.pdfTemplateAll[this.pdfTemplateSelectedIndex].templateContent : ''
    },
    closePreExport() {
      this.pdfExportShow = false
    },
    editPanel() {
      this.$emit('editPanel')
    }

  }
}
</script>

