const chart = {
  data() {
    return {
      sceneData: {},
      table: {},
      sceneId: {},
      viewId: {},
      tableId: {},
      chartSceneData: {}
    }
  },
  methods: {
    setSceneData(sceneData) {
      this.sceneData = sceneData
    },
    setTable(table) {
      this.table = table
    },
    setSceneId(sceneId) {
      this.sceneId = sceneId
    },
    setViewId(viewId) {
      this.viewId = viewId
    },
    setTableId(tableId) {
      this.tableId = tableId
    },
    setChartSceneData(chartSceneData) {
      this.chartSceneData = chartSceneData
    }
  }
}

export default chart
