<template>
  <div
    :style="getOutStyleDefault(config.style)"
    class="component"
    @click="handleClick"
    @mousedown="elementMouseDown"
  >
    <edit-bar
      v-if="componentActiveFlag"
      :element="config"
      :cur-component="curComponent"
      :component-data="componentData"
      :linkage-setting-status="linkageSettingStatus"
      :cur-linkage-view="curLinkageView"
      :style-change-times="styleChangeTimes"
      :canvas-style-data="canvasStyleData"
      @setShapeStyle="setShapeStyle"
      @setComponentDataTemp="setComponentDataTemp"
      @setCanvasStyleDataTemp="setCanvasStyleDataTemp"
      @setViewId="setViewId"
      @showViewDetails="showViewDetails"/>
    <close-bar v-if="previewVisible" @closePreview="closePreview" />
    <de-out-widget
      v-if="config.type==='custom'"
      :id="'component' + config.id"
      class="component-custom"
      :style="getComponentStyleDefault(config.style)"
      style="overflow: hidden"
      :out-style="config.style"
      :element="config"
      :in-screen="inScreen"
      :edit-mode="'preview'"
      :h="config.style.height"
      @AddViewFilterClick="onAddViewFilterClick"
    />
    <component
      :is="config.component"
      v-else
      ref="wrapperChild"
      :out-style="config.style"
      :style="getComponentStyleDefault(config.style)"
      :prop-value="config.propValue"
      :is-edit="false"
      :active="componentActiveFlag"
      :element="config"
      :search-count="searchCount"
      :h="config.style.height"
      :edit-mode="'preview'"
      :terminal="terminal"
      :component-data="componentData"
      :canvas-style-data="canvasStyleData"
      :now-panel-track-info="nowPanelTrackInfo"
      :now-panel-jump-info="nowPanelJumpInfo"
      :public-link-status="publicLinkStatus"
      :preview-canvas-scale="previewCanvasScale"
      :mobile-layout-status="mobileLayoutStatus"
      :cur-panel-info="panelInfo"
      :geo-map="geoMap"
      :token="token"
      :link-token="linkToken"
      @SetGeoClick="onSetGeoClick"
      @AddViewTrackFilterClick="onAddViewTrackFilterClick"
      @RecordStyleChangeClick="onRecordStyleChangeClick"
      @AddViewFilterClick="onAddViewFilterClick"
      @EmbendChartClick='onEmbendChartClick'
      @OpenChartDetailsDialogClick='onOpenChartDetailsDialogClick'
    />
  </div>
</template>

<script>
import { getStyle } from '@/components/canvas/utils/style'
import runAnimation from '@/components/canvas/utils/runAnimation'
import { mixins } from '@/components/canvas/utils/events'
// import { mapState } from 'vuex'
import DeOutWidget from '@/components/dataease/DeOutWidget'
import EditBar from '@/components/canvas/components/Editor/EditBar'
import CloseBar from '@/components/canvas/components/Editor/CloseBar'
import { uuid } from 'vue-uuid'

export default {
  components: { CloseBar, DeOutWidget, EditBar },
  mixins: [mixins],
  props: {
    config: {
      type: Object,
      require: true,
      default: null
    },
    filter: {
      type: Object,
      require: false,
      default: null
    },
    searchCount: {
      type: Number,
      required: false,
      default: 0
    },
    inScreen: {
      type: Boolean,
      required: false,
      default: true
    },
    terminal: {
      type: String,
      default: 'pc'
    },
    // 源 store 数据
    mobileLayoutStatus: {
      type: Boolean,
      default: false
    },
    canvasStyleData: {
      type: Object,
      default: null
    },
    curComponent: {
      type: Object,
      default: null
    },
    componentGap: {
      type: Number,
      default: 5
    },
    componentData: {
      type: Array,
      default: () => []
    },
    linkageSettingStatus: {
      type: Boolean,
      default: false
    },
    targetLinkageInfo: {
      type: Array,
      default: () => []
    },
    curLinkageView: {
      type: Object,
      default: null
    },
    styleChangeTimes: {
      type: Number,
      default: 0
    },
    nowPanelTrackInfo: {
      type: Object,
      default: () => {}
    },
    nowPanelJumpInfo: {
      type: Object,
      default: () => {}
    },
    publicLinkStatus: {
      type: Boolean,
      default: false
    },
    previewCanvasScale: {
      type: Object,
      default: () => ({
        scalePointWidth: 1,
        scalePointHeight: 1
      })
    },
    panelInfo: {
      type: Object,
      default: () => ({
        id: null,
        name: '',
        preStyle: null
      })
    },
    geoMap: {
      type: Object,
      default: () => {}
    },
    token: {
      type: String,
      default: null
    },
    linkToken: {
      type: String,
      default: null
    }
  },
  data() {
    return {
      previewVisible: false
    }
  },
  computed: {
    componentActiveFlag() {
      return (this.curComponent && this.config === this.curComponent) && !this.previewVisible
    },
    curGap() {
      return (this.canvasStyleData.panel.gap === 'yes' && this.config.auxiliaryMatrix) ? this.componentGap : 0
    }
    // ...mapState({
    //   mobileLayoutStatus: state => state.report.mobileLayoutStatus,
    //   canvasStyleData: state => state.report.canvasStyleData,
    //   curComponent: state => state.report.curComponent,
    //   componentGap: state => state.report.componentGap
    // })
  },
  mounted() {
    runAnimation(this.$el, this.config.animations)
  },
  methods: {
    onAddViewFilterClick(param) {
      this.$emit('AddViewFilterClick', param)
    },
    onRecordStyleChangeClick() {
      this.$emit('RecordStyleChangeClick')
    },
    setShapeStyle(param) {
      this.$emit('setShapeStyle', param)
    },
    setComponentDataTemp(param) {
      this.$emit('setComponentDataTemp', param)
    },
    setCanvasStyleDataTemp(param) {
      this.$emit('setCanvasStyleDataTemp', param)
    },
    setViewId(param) {
      this.$emit('setViewId', param)
    },
    onSetGeoClick(param) {
      this.$emit('SetGeoClick', param)
    },
    onAddViewTrackFilterClick(param) {
      this.$emit('AddViewTrackFilterClick', param)
    },
    onEmbendChartClick(param) {
      this.$emit('EmbendChartClick', param)
    },
    onOpenChartDetailsDialogClick(data) {
      this.$emit('OpenChartDetailsDialogClick', data)
    },
    getStyle,
    getShapeStyleIntDeDrag(style, prop) {
      if (prop === 'rotate') {
        return style['rotate']
      }
      if (prop === 'width') {
        return this.format(style['width'], this.scaleWidth)
      }
      if (prop === 'left') {
        return this.format(style['left'], this.scaleWidth)
      }
      if (prop === 'height') {
        return this.format(style['height'], this.scaleHeight)
      }
      if (prop === 'top') {
        const top = this.format(style['top'], this.scaleHeight)
        return top
      }
    },
    format(value, scale) {
      // 自适应画布区域 返回原值
      return value * scale / 100
    },
    getOutStyleDefault(style) {
      const result = {
        padding: this.curGap + 'px'
      }
      // 移动端编辑状态 且 未被移动端选中的组件 放满容器
      if (this.mobileLayoutStatus && !this.config.mobileSelected) {
        result.width = '100%'
        result.height = '100%'
      } else {
        ['width', 'left'].forEach(attr => {
          result[attr] = style[attr] + 'px'
        });
        ['height', 'top'].forEach(attr => {
          result[attr] = style[attr] + 'px'
        })
        result['rotate'] = style['rotate']
      }
      return result
    },

    getComponentStyleDefault(style) {
      // 移动端编辑状态 且 未被移动端选中的组件 放满容器
      if (this.mobileLayoutStatus && !this.config.mobileSelected) {
        return {
          width: '100%',
          height: '100%'
        }
      } else {
        if (this.terminal === 'pc') {
          return getStyle(style, ['top', 'left', 'width', 'height', 'rotate'])
        } else {
          return getStyle(style, ['top', 'left', 'width', 'height', 'rotate', 'fontSize'])
        }
      }
    },

    handleClick() {
      const events = this.config.events
      Object.keys(events).forEach(event => {
        this[event](events[event])
      })
    },
    elementMouseDown(e) {
      console.log('打印 ComponentWrapper.vue 里的 components is')
      console.log(this.config)

      // private 设置当前组件数据及状态
      // this.$store.commit('report/setClickComponentStatus', true)
      this.$emit('setClickComponentStatus', true)
      if (this.config.component !== 'v-text' && this.config.component !== 'rect-shape' && this.config.component !== 'de-input-search' && this.config.component !== 'de-select-grid' && this.config.component !== 'de-number-range' && this.config.component !== 'de-date') {
        e.preventDefault()
      }
      // 阻止冒泡事件
      e.stopPropagation()
      // this.$store.commit('report/setCurComponent', { component: this.config, index: this.index })
      this.$emit('setCurComponent', { component: this.config, index: this.index })
    },
    showViewDetails() {
      this.$refs.wrapperChild.openChartDetailsDialog()
    },
    closePreview() {
      this.previewVisible = false
    }
  }
}
</script>

<style lang="scss" scoped>
  .component {
    position: absolute;
  }

  .component:hover {
    box-shadow: 0px 0px 3px #0a7be0;
  }

  .gap_class {
    padding: 5px;
  }

  .component-custom {
    outline: none;
    width: 100% !important;
    height: 100%;
  }
</style>
